dsl:
name: baseline_rank_stop
rules:
  - id: loss
    type: rank
    score: "m1"
    select: {top: 1}
    weight: {total: 0.3}
    stop: {loss: 0.1, cooldown_bars: 2}
  - id: trail
    type: rank
    score: "m2"
    select: {top: 1}
    weight: {total: 0.3}
    stop: {trailing: 0.15, price: extreme}
  - id: profit
    type: rank
    side: short
    score: "m3"
    select: {bottom: 1}
    weight: {total: 0.3}
    stop: {profit: 0.2, cooldown_bars: 1}
portfolio:
  leverage: 1
  max_missing: 1
